383	    private boolean hasSelectedSingleNoteId() {
384	        //Heuristic to skip a large array copy
385	        if (checkedCardCount() > 50) {
386	            return false;
387	        }
388	        //copy to array to ensure threadsafe iteration
389	        Integer[] checkedPositions = mCheckedCardPositions.toArray(new Integer[0]);
390	        HashSet<String> notes = new HashSet<>();
391	        for (Integer position : checkedPositions) {
392	            String noteId = mCards.get(position).get(NOTE);
393	            if (notes.add(noteId) && notes.size() > 1) {
394	                return false;
395	            }
396	        }
397	        return notes.size() == 1;
398	    }
