private long[] getSelectedCardIds() {
    //copy to array to ensure threadsafe iteration
    Integer[] checkedPositions = mCheckedCardPositions.toArray(new Integer[0]);
    List<Map<String, String>> cards = getCards();
    //A position may no longer be valid: the list can be reloaded (searchCards()) while a selection is active.
    //Silently skip these instead of crashing with an IndexOutOfBoundsException.
    List<Long> ids = new ArrayList<>(checkedPositions.length);
    for (Integer cardPosition : checkedPositions) {
        if (cardPosition == null || cardPosition < 0 || cardPosition >= cards.size()) {
            Timber.w("Attempted to obtain the card at invalid position %s", cardPosition);
            continue;
        }
        String id = cards.get(cardPosition).get(ID);
        if (id == null) {
            continue;
        }
        ids.add(Long.parseLong(id));
    }
    long[] ret = new long[ids.size()];
    for (int i = 0; i < ids.size(); i++) {
        ret[i] = ids.get(i);
    }
    return ret;
}

/**
 * @return Whether all the currently selected cards belong to one single note.
 * Editing a note is only meaningful (and only supported) if this is the case.
 */
private boolean hasSelectedSingleNoteId() {
    //Heuristic to skip a large array copy
    if (checkedCardCount() > 50) {
        return false;
    }
    long[] cardIds = getSelectedCardIds();
    if (cardIds.length == 0) {
        return false;
    }
    try {
        //The "note" property of the browser list is the *note type* name, not the note id, and it isn't even
        //populated until a row has been rendered. So obtain the real note ids from the database.
        List<Long> noteIds = getCol().getDb().queryColumn(Long.class,
                "select distinct nid from cards where id in " + Utils.ids2str(cardIds), 0);
        return noteIds.size() == 1;
    } catch (Exception e) {
        Timber.w(e, "Failed to determine whether a single note is selected");
        return false;
    }
}

